INSERT INTO journeys (id,name,target_persona,description) VALUES ('J13','Visa & pháp lý dài hạn','P1','Đăng ký lưu trú, gia hạn, mất giấy tờ, chuyển trường, làm thêm hợp pháp, tốt nghiệp và rời khỏi Trung Quốc') ON CONFLICT DO NOTHING;
INSERT INTO journeys (id,name,target_persona,description) VALUES ('J14','Liên lạc với gia đình ở xa','P1','Duy trì liên lạc, báo bình an, chuyển tiền, chia sẻ đời sống, xử lý khẩn cấp và lên kế hoạch dài hạn cùng gia đình') ON CONFLICT DO NOTHING;
INSERT INTO journeys (id,name,target_persona,description) VALUES ('J15','Du lịch & khám phá Trung Quốc','P1','Vé tàu, khách sạn, thắng cảnh, mặc cả, xử lý sự cố khi đi du lịch trong kỳ nghỉ') ON CONFLICT DO NOTHING;
INSERT INTO journeys (id,name,target_persona,description) VALUES ('J16','Học thuật nâng cao','P1','Học bổng, hội nghị khoa học, thi cao học, liên hệ giáo sư, đăng bài báo khoa học') ON CONFLICT DO NOTHING;
INSERT INTO journeys (id,name,target_persona,description) VALUES ('J17','Ẩm thực & văn hoá ẩm thực','P1','Nhà hàng cao cấp, quy tắc bàn ăn, món ăn đặc sản vùng miền, văn hoá mời khách') ON CONFLICT DO NOTHING;
